`)}var mi=[{v:"1.0.54",date:"2026-11-22",text:"Safer records: staff can still sell, count cash and record GCash, but only the owner can void a GCash transaction, delete a day's cash record or use Fix profit on past sales. Cash counts and GCash entries can no longer be removed once saved. A waiting staff invite can only be changed by the store that sent it."},{v:"1.0.53",date:"2026-11-22",text:"Closing report: one click on the Dashboard (also on the phone page) shows the whole day on one page: sales, profit, expenses and net profit, how customers paid, the cash drawer and the last count, GCash, utang, Billiard & Gym, Carwash, who was on duty, the best sellers, and what to look at (cash or GCash short, voided sales, sales below cost). Copy or share it as text or as a picture to send in Messenger. Pick another day from the last 7 days."},{v:"1.0.52",date:"2026-11-19",text:"Observer: someone who is not staff (the owner or the software developer) can open the app from Who's on duty with Observe, using their PIN, to see how the store is doing without being on duty. Everything is view only, like the phone page; no one is put on duty and the duty and balance checks don't appear. Tap Stop observing at the top to choose who's on duty. The owner marks an observer in Store Setup > Staff on duty > Edit."},{v:"1.0.51",date:"2026-11-19",text:"Switch store from the Who's on duty screen: a button with the other store's name at the top right, so you can go to the other store before choosing who is on duty."},{v:"1.0.50",date:"2026-11-18",text:"Carwash, for a store that also runs a carwash: the owner turns it on in Store Setup and enters the price list (each service for motorcycle, sedan, SUV and pickup or van), the washers and their share. Staff tap the vehicle, tick the services, add the plate and washer, and save the sale as cash or GCash. The Carwash page shows today's washes; its Report shows sales, cars, what to pay each washer and what the store keeps, by service and by day, with Excel export. Carwash shows on the Dashboard with the other businesses and is kept apart from the store's sales."},{v:"1.0.49",date:"2026-11-16",text:"Inventory shows Expected profit next to Stock at selling price: what the stock in hand earns if it all sells at today's prices (selling price minus cost), with the margin. Items with no cost saved are not counted, and the card says how many."},{v:"1.0.48",date:"2026-11-16",text:"Send stock to another store (Inventory > Send to another store): stock goes down here and up at the other store; items it doesn't have are added there. Record it as a transfer at cost, or as a sale at your prices on the other store's utang. Transfers lists everything sent and received. Copy staff from another store (Store Setup): photos, labels and PINs carry over, so the same staff can be on duty at both stores."},{v:"1.0.47",date:"2026-11-16",text:"Switch store in one click: a button with the other store's name next to the store name at the top. Fixed: after switching stores, Team targets, GCash performance, the losing-items list and the comparisons no longer show numbers from the previous store."},{v:"1.0.46",date:"2026-11-15",text:"Own use (Expenses page): staff record store items taken for kitchen use, family food or snacks. Pick the items and how many; stock goes down and the cost (not the selling price) counts as an expense, so profit stays true. This month's own use shows by purpose. Deleting one puts the items back in stock. Own use is also a category for things bought outside with cash."},{v:"1.0.45",date:"2026-11-15",text:"GCash: prepaid load (Smart, TNT, Globe, GOMO) and bills payment (Meralco, water, internet and more) for customers. Record the network and number or the biller and account, the amount and your fee. The amount is paid from the store's GCash, so the Expected GCash balance goes down; fees count with GCash fees. Load and Bills totals show on the GCash page."},{v:"1.0.44",date:"2026-11-15",text:"Items losing money after login: 1 minute after choosing who's on duty, every item that sold below its saved cost (all time) is listed, and staff can Fix each one: the cost on past sales, and the item's cost and selling price for new sales. Do it later hides the list until the next login. Staff can now use Fix profit in the Sales report too."},{v:"1.0.43",date:"2026-11-15",text:"GCash performance on the GCash page: fees earned (the GCash profit), cash in, cash out and transactions for today, this week and this month (against the last period by this time) and for yesterday, last week and last month (against the one before), with fees per day for the last 30 days."},{v:"1.0.42",date:"2026-11-14",text:"Balance check is now every 3 hours and optional: staff can answer the cash, the GCash balance, both, or tap Skip for now. The owner can change how often in Store Setup > Staff on duty."},{v:"1.0.41",date:"2026-11-13",text:"Balance check: every 30 minutes staff must count the cash in the drawer and read the GCash app balance before they can continue. The expected amounts and any difference are shown after they answer, and saved in Cash counts and GCash. The owner can change how often in Store Setup > Staff on duty."},{v:"1.0.40",date:"2026-11-13",text:"Compared with the past for GCash and Billiard & Gym: GCash fees, cash in and cash out, and billiard and gym sales, against the same dates 1 week, 1 month and 1 year ago (up to this time of day for today)."},{v:"1.0.39",date:"2026-11-13",text:"Staff can have a label (for example Store manager or Software creator), set in Store Setup > Staff on duty, shown under their name when choosing who's on duty."},{v:"1.0.38",date:"2026-11-13",text:"Who's on duty shows who is on duty now, on this counter and at other counters. Every 20 minutes the app asks again who is really on duty, with PINs checked again; it waits until the sale in progress is finished. The owner can change how often in Store Setup > Staff on duty."},{v:"1.0.37",date:"2026-11-10",text:"Share picture on Today's top 10 best sellers and Team targets: copies a picture of the card, with the store name and time, to paste into the team chat. It can also be saved as a picture."},{v:"1.0.36",date:"2026-11-10",text:"Team targets show whether the team is on track: compared with yesterday, last week or last month by this same time, with a mark on each bar."},{v:"1.0.35",date:"2026-11-10",text:"Team targets on the Dashboard: net profit, transactions and sales for today, this week and this month, against all of yesterday, last week and last month. When the team beats one, every staff member earns a bonus; the owner sets the amounts."},{v:"1.0.34",date:"2026-11-10",text:"Gym memberships can now be half a month (15 days). GCash cash in: the amount goes to the GCash account, so it no longer counts in Cash in drawer; choose whether the fee was paid in cash (stays in the drawer) or by GCash."},{v:"1.0.33",date:"2026-11-09",text:"Forced update: a sale left in the cart with no change for 10 minutes no longer holds back the update. The items stay in the cart after the restart."},{v:"1.0.32",date:"2026-11-09",text:"Cash count: count the cash drawer (every hour by default) and the POS compares it with the expected cash. Choose who counted, with their PIN. The Dashboard shows the last count and when the next is due; a Cash count due reminder shows at the top on every page. History per day; the owner sets how often."},{v:"1.0.31",date:"2026-11-09",text:"Dashboard shows the GCash balance: what the store's GCash app should show now, and the result of the last check. Check it or set the starting balance right from the Dashboard."},{v:"1.0.30",date:"2026-11-09",text:"Billiard & Gym: start and stop a clock on each billiard table and charge by the hour; gym walk-ins (day pass), members with monthly memberships, renewals and check-ins. Their own report and Excel export, kept apart from the store's sales, with a total for all three businesses on the Dashboard."},{v:"1.0.29",date:"2026-11-09",text:"Forced update: when a new version is downloaded, the app restarts to install it, after the sale in progress is finished and waiting sales are uploaded, with a 30-second countdown. It looks for new versions every 30 minutes."},{v:"1.0.28",date:"2026-11-09",text:"When the app opens, it asks who the head staff on duty is and whether there is an assistant (or No assistant) before anyone can use it. PINs are checked; the same person still on duty from today keeps their time in. A time in left open overnight is closed at the time the app was last running."},{v:"1.0.27",date:"2026-11-09",text:"The store computer stays signed in, even after closing the app, restarting or updating. Sign out is gone from the sidebar; only the owner can sign a computer out, in Store Setup > Account & sync. The phone page keeps its Sign out."},{v:"1.0.26",date:"2026-11-09",text:"Software updates window: this computer's version, the latest release, and what changed in every version. After an update, a note at the top links to what's new."},{v:"1.0.25",date:"2026-11-08",text:"Items losing money: a list of every item with profit below zero, with the likely cause, a Fix button, and Save as PDF for review. Bought by: set how you buy an item (piece, dozen, box, pack, case, bundle or sack) and the box cost; the cost of each piece is worked out. Restock in boxes or pieces. Row numbers in Item sales and Inventory."},{v:"1.0.23",date:"2026-11-08",text:"Fix profit: the owner can correct an item's cost or total profit in Sales report > Item sales, and every profit number updates to match."},{v:"1.0.22",date:"2026-11-08",text:"Fix out-of-date data (Store Setup > Data on this computer): uploads anything waiting, then downloads a fresh copy of the store's data from the cloud."},{v:"1.0.21",date:"2026-11-08",text:"Removed Check a receipt (the AI receipt reader) from Inventory."},{v:"1.0.20",date:"2026-11-08",text:"Fixed: versions 1.0.18 and 1.0.19 could open to a blank dark screen."},{v:"1.0.19",date:"2026-11-08",text:"Installs for your Windows account only, so updates no longer ask for Windows permission."},{v:"1.0.18",date:"2026-11-08",text:"Refresh button next to Synced to cloud. The Dashboard shows who is on duty at other counters."},{v:"1.0.17",date:"2026-11-08",text:"Sort Item sales by highest sales, highest profit, most sold, profit each, losses first, least sold, lowest stock left or name."},{v:"1.0.16",date:"2026-11-08",text:"Fixed: the All time sales report now includes every sale from the first day."},{v:"1.0.15",date:"2026-11-08",text:"All time sales report with a graph. Sales report compares with 1 week, 1 month and 1 year ago."},{v:"1.0.14",date:"2026-11-08",text:"Staff can change their time in and time out. Time log with hours per person and an Excel download."},{v:"1.0.13",date:"2026-11-08",text:"Head staff and assistant on duty, shown on the Dashboard, saved on each sale and in the Sales report."},{v:"1.0.12",date:"2026-11-08",text:"More Dashboard numbers: profit per \u20B1100, net profit after expenses, profit per sale, items sold, stock worth and more. GCash current balance check."},{v:"1.0.11",date:"2026-11-08",text:"Version number and Check for updates at the bottom of the sidebar."},{v:"1.0.10",date:"2026-11-08",text:"Sales & profit graph. Dashboard top 10 lists. Shopping list for out-of-stock items. Optional customer name at checkout. GCash keeps only the last 4 digits of the reference."},{v:"1.0.9",date:"2026-11-08",text:"Staff on duty: staff with a photo and optional PIN switch by tapping their photo. Each sale records who was on duty."},{v:"1.0.8",date:"2026-11-08",text:"The newest scanned item shows at the top of Current sale, highlighted for a moment."},{v:"1.0.7",date:"2026-11-07",text:"Profit each and Remaining stock in Item sales. Losses shown in red. Reset stock for recounting, with a backup file and Undo."},{v:"1.0.6",date:"2026-11-07",text:"Profit column, sorting and filters in Inventory. Cost change warnings and history. Supplier on restock. The app now updates itself."},{v:"1.0.2",date:"2026-11-07",text:"GCash cash in and cash out."},{v:"1.0.1",date:"2026-11-06",text:"First release: selling with a barcode scanner, cash and GCash, receipts, inventory, sales reports, staff sign-in, and cloud sync between counters and the phone."}];function lo(n,t){let e=String(n||"").replace(/^v/,"").split(".").map(i=>parseInt(i,10)||0),s=String(t||"").replace(/^v/,"").split(".").map(i=>parseInt(i,10)||0);for(let i=0;i<Math.max(e.length,s.length);i++){let r=(e[i]||0)-(s[i]||0);if(r)return r}return 0}function $_(n,t){return(n||[]).filter(e=>e&&e.v&&lo(e.v,t)>0).sort((e,s)=>lo(s.v,e.v))}function x_(n){let t=/^(download \*\*tindahan-pos|if you have version 1\.0\.3|if windows shows|\*\*if (tindahan pos opens|your computer had|tindahan pos is already))/i;return String(n||"").replace(/\r\n/g,`
